frappe.listview_settings['Attendance Request'] = {
    add_fields: ['custom_late_category', 'custom_late_by_minutes', 'docstatus', 'reason'],

    get_indicator: function (doc) {
        if (doc.docstatus === 1) return [__('Approved'), 'green', 'docstatus,=,1'];
        if (doc.docstatus === 2) return [__('Rejected'), 'red', 'docstatus,=,2'];
        return [__('Draft'), 'orange', 'docstatus,=,0'];
    },

    formatters: {
        // minutes -> "2 hr 36 min", coloured by how late it was
        custom_late_by_minutes: function (value, df, doc) {
            var m = parseInt(value || 0, 10);
            if (!m) return '';
            var h = Math.floor(m / 60), mm = m % 60;
            var txt = h ? (mm ? h + ' hr ' + mm + ' min' : h + ' hr') : mm + ' min';
            var colour = m <= 15 ? '#b58100'
                       : m <= 30 ? '#e8730c'
                       : m <= 60 ? '#7c4dff'
                       : m <= 120 ? '#d6336c' : '#c0392b';
            return '<span style="color:' + colour + ';font-weight:600;">' + txt + '</span>';
        },
        custom_late_category: function (value) {
            if (!value) return '';
            var bg = {
                'Late \u226415 min': '#fff8e1',
                'Late 15-30 min': '#fff1e0',
                'Late 30-60 min': '#f3ecff',
                'Late 1-2 hr': '#ffeaf2',
                'Late >2 hr': '#ffecea'
            }[value] || '#f2f4f6';
            var fg = {
                'Late \u226415 min': '#b58100',
                'Late 15-30 min': '#e8730c',
                'Late 30-60 min': '#7c4dff',
                'Late 1-2 hr': '#d6336c',
                'Late >2 hr': '#c0392b'
            }[value] || '#5a6b78';
            return '<span style="background:' + bg + ';color:' + fg +
                   ';padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;">' +
                   __(value) + '</span>';
        }
    }
};

frappe.ui.form.on('Logikview Appraisal', {
    employee(frm) {
        // pull the parameter set + reviewer chain as soon as an employee is chosen,
        // so a hand-created appraisal looks exactly like an auto-generated one
        if (!frm.doc.employee) return;
        frappe.call({
            method: 'logikview_hr.appraisal.resolve_defaults',
            args: { employee: frm.doc.employee },
            callback: (r) => {
                const d = r.message;
                if (!d) return;
                ['assessment_type', 'reporting_officer', 'first_director',
                 'second_director', 'cc_director', 'needs_second_director'].forEach(f => {
                    if (!frm.doc[f]) frm.set_value(f, d[f]);
                });
                if (!(frm.doc.ratings || []).length && (d.ratings || []).length) {
                    frm.clear_table('ratings');
                    d.ratings.forEach(row => {
                        const c = frm.add_child('ratings');
                        c.category = row.category;
                        c.parameter = row.parameter;
                    });
                    frm.refresh_field('ratings');
                }
            }
        });
    },

    onload(frm) {
        // if the user can only pick one employee (i.e. themselves), preselect it
        if (frm.is_new() && !frm.doc.employee) {
            frappe.call({
                method: 'logikview_hr.queries.default_employee',
                callback: (r) => { if (r.message) frm.set_value('employee', r.message); }
            });
        }
    },

    refresh(frm) {
        const me = frappe.session.user;
        const st = frm.doc.workflow_state;
        const isEmp = me === frm.doc.employee_user;
        const isRO  = me === frm.doc.ro_user;
        const isD1  = me === frm.doc.first_director_user;
        const isD2  = me === frm.doc.second_director_user;
        const isHR  = frappe.user.has_role('HR Manager') || frappe.user.has_role('System Manager');

        const empEdit = (!st || st === 'Pending Self-Assessment') && (isEmp || isHR);
        const roEdit  = (st === 'Pending Manager Review')   && (isRO  || isHR);
        const d1Edit  = (st === 'Pending Director Review')  && (isD1  || isHR);
        const d2Edit  = (st === 'Pending Final Director')   && (isD2  || isHR);

        // the parameter list is fixed: no adding, no deleting, no editing the text
        const grid = frm.fields_dict.ratings.grid;
        grid.cannot_add_rows = true;
        if (grid.df) { grid.df.cannot_add_rows = true; }
        grid.update_docfield_property('category',  'read_only', 1);
        grid.update_docfield_property('parameter', 'read_only', 1);
        grid.update_docfield_property('employee_rating', 'read_only', empEdit ? 0 : 1);
        grid.update_docfield_property('ro_rating',       'read_only', roEdit  ? 0 : 1);
        frm.refresh_field('ratings');
        if (grid.wrapper) {
            grid.wrapper.find('.grid-add-row, .grid-remove-rows, .grid-remove-all-rows').hide();
        }

        // narratives (employee)
        ['q_accomplishments', 'q_not_accomplished', 'q_goals'].forEach(f =>
            frm.set_df_property(f, 'read_only', empEdit ? 0 : 1));

        // Feedback is open to any senior in this employee's reporting line
        // (both managers at every level), the directors and HR - not locked to
        // one person at one exact stage. Ratings stay stage-gated.
        const seniors = (frm.doc.senior_users || '').split(',').filter(Boolean);
        const isSenior = isHR || seniors.indexOf(me) !== -1;
        const done = st === 'Completed';
        const fbEdit = isSenior && (!done || isHR);   // after completion only HR may amend

        frm.set_df_property('ro_feedback', 'read_only', fbEdit ? 0 : 1);
        frm.set_df_property('first_director_feedback',  'read_only', fbEdit ? 0 : 1);
        frm.set_df_property('second_director_feedback', 'read_only', fbEdit ? 0 : 1);
        if (fbEdit && !done) {
            frm.set_df_property('ro_feedback', 'description',
                'Open to any senior authority - add or refine feedback as needed.');
        }

        const hint = {
            'Pending Self-Assessment': 'Employee to fill the self-assessment (Your Rating + the three questions).',
            'Pending Manager Review':  'Reporting officer to fill the RO Rating column.',
            'Pending Director Review': 'Director to add their feedback comment.',
            'Pending Final Director':  'Final director to add closing feedback.',
            'Completed':               'Appraisal completed.'
        }[st];
        if (hint) frm.dashboard.set_headline(hint);
    }
});

frappe.ui.form.on('Fun Friday Idea', {
    refresh(frm) {
        if (frm.is_new()) return;
        const me = frappe.session.user;
        const liked = (frm.doc.votes || []).some(v => v.user === me);
        frm.add_custom_button(liked ? '\u2665 Liked (' + (frm.doc.vote_count || 0) + ')'
                                    : '\u2661 Like (' + (frm.doc.vote_count || 0) + ')', () => {
            frappe.call({
                method: 'logikview_hr.logikview_hr.doctype.fun_friday_idea.fun_friday_idea.toggle_like',
                args: { idea: frm.doc.name },
                callback: () => frm.reload_doc()
            });
        });
        frm.dashboard.set_headline(
            'Fun Friday is every Friday, 5:00 - 6:00 PM. Add your idea and like the ones you want to do!'
        );
    }
});

frappe.listview_settings['Fun Friday Idea'] = {
    add_fields: ['status', 'vote_count'],
    get_indicator: function (doc) {
        const map = { 'Proposed': 'blue', 'Shortlisted': 'orange', 'Scheduled': 'purple', 'Done': 'green' };
        return [__(doc.status) + ' \u00b7 \u2665 ' + (doc.vote_count || 0),
                map[doc.status] || 'grey', 'status,=,' + doc.status];
    }
};

frappe.ui.form.on('Employee', {
    refresh(frm) {
        // the stock pickers list every user in the system - restrict them to the
        // people who are actually authorised to approve
        const approver_query = { query: 'logikview_hr.queries.approver_query' };
        ['expense_approver', 'leave_approver', 'shift_request_approver'].forEach(f => {
            if (frm.fields_dict[f]) frm.set_query(f, () => approver_query);
        });
    }
});

frappe.listview_settings['Employee Checkin'] = {
    add_fields: ['device_id', 'custom_auto_checkout', 'log_type'],

    get_indicator: function (doc) {
        if (doc.log_type === 'IN')  return [__('IN'),  'green',  'log_type,=,IN'];
        if (doc.log_type === 'OUT') return [__('OUT'), 'orange', 'log_type,=,OUT'];
        return [__(doc.log_type || ''), 'grey', ''];
    },

    formatters: {
        // where the person actually was, from the device GPS at check-in
        device_id: function (value, df, doc) {
            if (!value) return '';
            var wfh = String(value).toLowerCase().indexOf('home') !== -1;
            var office = String(value).toLowerCase().indexOf('office') !== -1;
            var label = wfh ? 'WFH' : (office ? 'OFC' : value);
            var bg = wfh ? '#e8f1ff' : (office ? '#e7f7ee' : '#f2f4f6');
            var fg = wfh ? '#1263d1' : (office ? '#17794f' : '#5a6b78');
            var pill = '<span style="background:' + bg + ';color:' + fg +
                       ';padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">' +
                       label + '</span>';
            if (doc && doc.custom_auto_checkout) {
                pill += ' <span title="Checked out automatically by the system" ' +
                        'style="color:#8a94a0;font-size:11px;">auto</span>';
            }
            return pill;
        },
        custom_auto_checkout: function (value) {
            return value
                ? '<span style="color:#8a94a0;font-weight:600;">\u2713 Auto</span>'
                : '';
        }
    }
};

frappe.ui.form.on('Employee', {
    refresh(frm) {
        // hidden for everyone except the Administrator account
        if (frappe.session.user === 'Administrator') return;
        setTimeout(function () {
            $(frm.wrapper).find('.form-assignments, .form-tags, .form-shared').hide();
        }, 300);
    }
});

frappe.ui.form.on('Employee', {
    refresh(frm) {
        // Exempt from Attendance Tracking is for directors/admin only, not HR
        if (frappe.user.has_role('System Manager')) return;
        frm.set_df_property('custom_exempt_from_attendance', 'hidden', 1);
        frm.refresh_field('custom_exempt_from_attendance');
    }
});

frappe.listview_settings['Employee'] = frappe.listview_settings['Employee'] || {};
(function () {
    var orig = frappe.listview_settings['Employee'].onload;
    frappe.listview_settings['Employee'].onload = function (listview) {
        if (orig) orig(listview);
        if (frappe.user.has_role('System Manager')) return;
        setTimeout(function () {
            $('[data-fieldname="custom_exempt_from_attendance"]')
                .closest('.filter-field, .standard-filter-section, .list-sidebar-label').hide();
        }, 800);
    };
})();
